 22: static USAGE: &'static str = "
 23: Computes basic statistics on CSV data.
 24: 
 25: Basic statistics includes mean, median, mode, standard deviation, sum, max and
 26: min values. Note that some statistics are expensive to compute, so they must
 27: be enabled explicitly. By default, the following statistics are reported for
 28: *every* column in the CSV data: mean, max, min and standard deviation. The
 29: default set of statistics corresponds to statistics that can be computed
 30: efficiently on a stream of data (i.e., constant memory).
 31: 
 32: Computing statistics on a large file can be made much faster if you create
 33: an index for it first with 'xsv index'.
 34: 
 35: Usage:
 36:     xsv stats [options] [<input>]
 37: 
 38: stats options:
 39:     -s, --select <arg>     Select a subset of columns to compute stats for.
 40:                            See 'xsv select --help' for the format details.
 41:                            This is provided here because piping 'xsv select'
 42:                            into 'xsv stats' will disable the use of indexing.
 43:     --everything           Show all statistics available.
 44:     --mode                 Show the mode.
 45:                            This requires storing all CSV data in memory.
 46:     --cardinality          Show the cardinality.
 47:                            This requires storing all CSV data in memory.
 48:     --median               Show the median.
 49:                            This requires storing all CSV data in memory.
 50:     --nulls                Include NULLs in the population size for computing
 51:                            mean and standard deviation.
 52:     -j, --jobs <arg>       The number of jobs to run in parallel.
 53:                            This works better when the given CSV data has
 54:                            an index already created. Note that a file handle
 55:                            is opened for each job.
 56:                            When set to '0', the number of jobs is set to the
 57:                            number of CPUs detected.
 58:                            [default: 0]
 59: 
 60: Common options:
 61:     -h, --help             Display this message
 62:     -o, --output <file>    Write output to <file> instead of stdout.
 63:     -n, --no-headers       When set, the first row will NOT be interpreted
 64:                            as column names. i.e., They will be included
 65:                            in statistics.
 66:     -d, --delimiter <arg>  The field delimiter for reading CSV data.
 67:                            Must be a single character. (default: ,)
 68: ";
 69: 
 70: #[derive(Clone, Deserialize)]
 71: struct Args {
 72:     arg_input: Option<String>,
 73:     flag_select: SelectColumns,
 74:     flag_everything: bool,
 75:     flag_mode: bool,
 76:     flag_cardinality: bool,
 77:     flag_median: bool,
 78:     flag_nulls: bool,
 79:     flag_jobs: usize,
 80:     flag_output: Option<String>,
 81:     flag_no_headers: bool,
 82:     flag_delimiter: Option<Delimiter>,
 83: }
 84: 
 85: pub fn run(argv: &[&str]) -> CliResult<()> {
 86:     let args: Args = util::get_args(USAGE, argv)?;
 87: 
 88:     let mut wtr = Config::new(&args.flag_output).writer()?;
 89:     let (headers, stats) = match args.rconfig().indexed()? {
 90:         None => args.sequential_stats(),
 91:         Some(idx) => {
 92:             if args.flag_jobs == 1 {
 93:                 args.sequential_stats()
 94:             } else {
 95:                 args.parallel_stats(idx)
 96:             }
 97:         }
 98:     }?;
 99:     let stats = args.stats_to_records(stats);
100: 
101:     wtr.write_record(&args.stat_headers())?;
102:     let fields = headers.iter().zip(stats.into_iter());
103:     for (i, (header, stat)) in fields.enumerate() {
104:         let header =
105:             if args.flag_no_headers {
106:                 i.to_string().into_bytes()
107:             } else {
108:                 header.to_vec()
109:             };
110:         let stat = stat.iter().map(|f| f.as_bytes());
111:         wtr.write_record(vec![&*header].into_iter().chain(stat))?;
112:     }
113:     wtr.flush()?;
114:     Ok(())
115: }
