117: impl Args {
118:     fn sequential_stats(&self) -> CliResult<(csv::ByteRecord, Vec<Stats>)> {
119:         let mut rdr = self.rconfig().reader()?;
120:         let (headers, sel) = self.sel_headers(&mut rdr)?;
121:         let stats = self.compute(&sel, rdr.byte_records())?;
122:         Ok((headers, stats))
123:     }
124: 
125:     fn parallel_stats(
126:         &self,
127:         idx: Indexed<fs::File, fs::File>,
128:     ) -> CliResult<(csv::ByteRecord, Vec<Stats>)> {
129:         // N.B. This method doesn't handle the case when the number of records
130:         // is zero correctly. So we use `sequential_stats` instead.
131:         if idx.count() == 0 {
132:             return self.sequential_stats();
133:         }
134: 
135:         let mut rdr = self.rconfig().reader()?;
136:         let (headers, sel) = self.sel_headers(&mut rdr)?;
137: 
138:         let chunk_size = util::chunk_size(idx.count() as usize, self.njobs());
139:         let nchunks = util::num_of_chunks(idx.count() as usize, chunk_size);
140: 
141:         let pool = ThreadPool::new(self.njobs());
142:         let (send, recv) = chan::sync(0);
143:         for i in 0..nchunks {
144:             let (send, args, sel) = (send.clone(), self.clone(), sel.clone());
145:             pool.execute(move || {
146:                 let mut idx = args.rconfig().indexed().unwrap().unwrap();
147:                 idx.seek((i * chunk_size) as u64).unwrap();
148:                 let it = idx.byte_records().take(chunk_size);
149:                 send.send(args.compute(&sel, it).unwrap());
150:             });
151:         }
152:         drop(send);
153:         Ok((headers, merge_all(recv.iter()).unwrap_or_else(Vec::new)))
154:     }
