156:     fn stats_to_records(&self, stats: Vec<Stats>) -> Vec<csv::StringRecord> {
157:         let mut records: Vec<_> = repeat(csv::StringRecord::new())
158:             .take(stats.len())
159:             .collect();
160:         let pool = ThreadPool::new(self.njobs());
161:         let mut results = vec![];
162:         for mut stat in stats.into_iter() {
163:             let (send, recv) = chan::sync(0);
164:             results.push(recv);
165:             pool.execute(move || { send.send(stat.to_record()); });
166:         }
167:         for (i, recv) in results.into_iter().enumerate() {
168:             records[i] = recv.recv().unwrap();
169:         }
170:         records
171:     }
