173:     fn compute<I>(&self, sel: &Selection, it: I) -> CliResult<Vec<Stats>>
174:             where I: Iterator<Item=csv::Result<csv::ByteRecord>> {
175:         let mut stats = self.new_stats(sel.len());
176:         for row in it {
177:             let row = row?;
178:             for (i, field) in sel.select(&row).enumerate() {
179:                 stats[i].add(field);
180:             }
181:         }
182:         Ok(stats)
183:     }
