 384: #[derive(Clone, Copy, PartialEq)]
 385: enum FieldType {
 386:     TUnknown,
 387:     TNull,
 388:     TUnicode,
 389:     TFloat,
 390:     TInteger,
 391: }
 392: 
 393: impl FieldType {
 394:     fn from_sample(sample: &[u8]) -> FieldType {
 395:         if sample.is_empty() {
 396:             return TNull;
 397:         }
 398:         let string = match str::from_utf8(sample) {
 399:             Err(_) => return TUnknown,
 400:             Ok(s) => s,
 401:         };
 402:         if let Ok(_) = string.parse::<i64>() { return TInteger; }
 403:         if let Ok(_) = string.parse::<f64>() { return TFloat; }
 404:         TUnicode
 405:     }
 406: 
 407:     fn is_number(&self) -> bool {
 408:         *self == TFloat || *self == TInteger
 409:     }
 410: 
 411:     fn is_null(&self) -> bool {
 412:         *self == TNull
 413:     }
 414: }
 415: 
 416: impl Commute for FieldType {
 417:     fn merge(&mut self, other: FieldType) {
 418:         *self = match (*self, other) {
 419:             (TUnicode, TUnicode) => TUnicode,
 420:             (TFloat, TFloat) => TFloat,
 421:             (TInteger, TInteger) => TInteger,
 422:             // Null does not impact the type.
 423:             (TNull, any) | (any, TNull) => any,
 424:             // There's no way to get around an unknown.
 425:             (TUnknown, _) | (_, TUnknown) => TUnknown,
 426:             // Integers can degrate to floats.
 427:             (TFloat, TInteger) | (TInteger, TFloat) => TFloat,
 428:             // Numbers can degrade to Unicode strings.
 429:             (TUnicode, TFloat) | (TFloat, TUnicode) => TUnicode,
 430:             (TUnicode, TInteger) | (TInteger, TUnicode) => TUnicode,
 431:         };
 432:     }
 433: }
 434: 
 435: impl Default for FieldType {
 436:     // The default is the most specific type.
 437:     // Type inference proceeds by assuming the most specific type and then
 438:     // relaxing the type as counter-examples are found.
 439:     fn default() -> FieldType { TNull }
 440: }
